-- JR Kyushu 2026-03-14 regular timetable, printed page 3 (PDF page index 2).
-- https://www.jrkyushu.co.jp/english/pdf/timetable_20260314_20270228.pdf
-- Weekday/SaturdayHoliday is the ONLY calendar. 20260314 is source revision.
-- Calling times are unqualified source clocks, with no guessed dwell times.
BEGIN;
CREATE TEMP TABLE kyu_p2_services(key text PRIMARY KEY,train_number text,dir text) ON COMMIT DROP;
CREATE TEMP TABLE kyu_p2_stops(key text,seq int,station text,clock text,is_last boolean) ON COMMIT DROP;
DO $$BEGIN IF (SELECT count(*) FROM kyu_p2_services)<>36 OR
 EXISTS(SELECT 1 FROM kyu_p2_services t WHERE (SELECT count(*) FROM kyu_p2_stops s WHERE s.key=t.key)<2)
THEN RAISE EXCEPTION 'Source p2 count/stop integrity failed';END IF;END$$;
SELECT 'KyushuShinkansen','odpt.Calendar:SaturdayHoliday',t.train_number,
'odpt.Railway:JR-Kyushu.KyushuShinkansen','odpt.RailDirection:'||t.dir,
'odpt.TrainType:JR-Kyushu.Shinkansen',
ARRAY[(SELECT station FROM kyu_p2_stops s WHERE s.key=t.key ORDER BY seq DESC LIMIT 1)],
'official-sampled:holiday:https://www.jrkyushu.co.jp/english/pdf/timetable_20260314_20270228.pdf',t.key
FROM kyu_p2_services t
WHERE NOT EXISTS(SELECT 1 FROM manual_timetable_templates m WHERE m.source_trip_id=t.key AND m.calendar_urn='odpt.Calendar:SaturdayHoliday');
CREATE TEMP TABLE kyu_p2_map ON COMMIT DROP AS
SELECT t.key,m.id FROM kyu_p2_services t JOIN manual_timetable_templates m ON m.source_trip_id=t.key AND m.calendar_urn='odpt.Calendar:SaturdayHoliday' AND m.line_key='KyushuShinkansen';
DO $$ BEGIN IF (SELECT count(*) FROM kyu_p2_map)<>36 THEN RAISE EXCEPTION 'Expected 36 source mappings'; END IF;END$$;
SELECT m.id,s.seq,CASE WHEN s.is_last THEN s.station END,CASE WHEN NOT s.is_last THEN s.station END,
CASE WHEN s.is_last THEN s.clock END,CASE WHEN NOT s.is_last THEN s.clock END
FROM kyu_p2_map m JOIN kyu_p2_stops s ON s.key=m.key
WHERE NOT EXISTS(SELECT 1 FROM manual_timetable_template_stops e WHERE e.template_id=m.id AND e.stop_sequence=s.seq);
SELECT 'source:'||m.id,'odpt.Calendar:SaturdayHoliday',t.train_number,m.id,'source_only','undated_not_current_verified'
FROM kyu_p2_map m JOIN manual_timetable_templates t ON t.id=m.id
WHERE NOT EXISTS(SELECT 1 FROM train_timetables old WHERE old.lead_source_template_id=m.id);
SELECT m.id,t.id,0,'primary',0,(SELECT max(stop_sequence) FROM manual_timetable_template_stops s WHERE s.template_id=m.id),0,false
FROM kyu_p2_map m JOIN train_timetables t ON t.lead_source_template_id=m.id
WHERE NOT EXISTS(SELECT 1 FROM train_timetable_members old WHERE old.source_template_id=m.id);
DO $$BEGIN IF EXISTS(SELECT 1 FROM kyu_p2_map m
 WHERE (SELECT count(*) FROM manual_timetable_template_stops s WHERE s.template_id=m.id) <>
 (SELECT count(*) FROM kyu_p2_stops s WHERE s.key=m.key)
 OR NOT EXISTS(SELECT 1 FROM train_timetable_members tm WHERE tm.source_template_id=m.id))
THEN RAISE EXCEPTION 'New JR Kyushu plan missing stops/membership';END IF;END$$;
WITH c AS(SELECT line_key,count(*)::integer n,count(distinct calendar_urn)::integer cal,count(distinct direction_urn)::integer dir,count(*) filter(where source_path like 'official-sampled:%')::integer sampled FROM manual_timetable_templates WHERE line_key='KyushuShinkansen' GROUP BY 1)
UPDATE published_timetable_coverage_audit a
SET template_count=c.n,calendar_count=c.cal,direction_count=c.dir,sampled_count=c.sampled,
issues=(SELECT array_agg(DISTINCT i ORDER BY i) FROM unnest(a.issues||ARRAY['KYUSHU_2026_HOLIDAY_REGULAR_P2_IMPORTED']::text[]) i),
checked_at=now() FROM c WHERE c.line_key=a.line_key;
COMMIT;